  if(!data){view.innerHTML=`<div class="player-empty"><i data-lucide="user-round"></i><span>${esc(t("artistEmpty"))}</span></div>`;icon();return;}
  if(data.loading){view.innerHTML=`<div class="player-empty"><i data-lucide="loader-circle" class="spin"></i><span>${esc(t("loading"))}</span></div>`;icon();return;}
  if(data.error){view.innerHTML=`<div class="player-empty"><i data-lucide="triangle-alert"></i><span>${esc(data.error)}</span></div>`;icon();return;}
