function insertAfterCurrent(track) { const item={...plainTrack(track),_sourceType:"track",_sourceKey:`track/${track.id}`}; if(state.current<0){state.queue.push(item);renderQueue();if(state.queue.length===1)playIndex(0);return;} state.queue.splice(state.current+1,0,item); renderQueue(); }
function selectTrack(track) { state.selectedTrackId=track?String(track.id):null; if(track){state.selectedInfo={...plainTrack(track)};state.albumInfo=null;} renderQueue(); renderArtistSelection(); showPanelForSelection(track); }
function showPanelForSelection(track) { if(!track)return; if(track.artist_id)openArtistPage(track.artist_id,false); if(state.panelTab==="info")renderInfo(); }
async function openAlbumInfo(albumId) { if(!albumId)return; showPanelTab("info"); const view=$("#infoView"); view.innerHTML=`<div class="player-empty"><i data-lucide="loader-circle" class="spin"></i><span>${esc(t("loading"))}</span></div>`; icon(); try { const data=await api("/api/player/resource",{method:"POST",body:JSON.stringify({resource:`album/${albumId}`})}); const tracks=data.tracks||[]; const first=tracks[0]||{}; state.albumInfo={album_id:String(albumId),title:first.title||"",artist:first.artist||"",cover:first.cover||"",duration:tracks.reduce((sum,t)=>sum+(t.duration||0),0),trackCount:tracks.length}; } catch(error) { state.albumInfo={album_id:String(albumId),title:error.message,artist:"",cover:"",duration:0,trackCount:0}; } renderInfo(); }
function renderArtistSelection() { document.querySelectorAll("[data-artist-album]").forEach(el=>el.classList.remove("selected")); if(!state.artistView)return; const items=artistEntries(); items.forEach((entry,i)=>{ if(String(entry.id)===String(state.selectedTrackId))document.querySelector(`[data-artist-album="${i}"]`)?.classList.add("selected"); }); }
function playSingleFavorite(track) { const id=String(track.id); const inAlbum=state.queue.findIndex(t=>String(t.id)===id&&t._sourceType==="album"); if(inAlbum>=0)return playIndex(inAlbum); const item={...plainTrack(track),_sourceType:"track",_sourceKey:`track/${id}`}; const existing=state.queue.findIndex(t=>String(t.id)===id); if(existing>=0){state.queue.splice(existing,1);if(state.current>existing)state.current--;} state.queue.unshift(item); state.current=state.current>=0?state.current+1:0; renderQueue(); playIndex(0); }
function toggleFavorite() { const track=state.queue[state.current]; if(track)toggleFavoriteEntry(plainTrack(track)); }
function updateFavoriteButton() { const track=state.queue[state.current]; const active=Boolean(track&&isTrackFavorited(track)); const button=$("#favoriteButton"); button.disabled=!track; button.classList.toggle("fav-active",active); button.dataset.title=active?"unfavorite":"favorite"; button.title=t(active?"unfavorite":"favorite"); button.setAttribute("aria-label",button.title); button.innerHTML=`<i data-lucide="heart"></i>`; icon(); }
function updateDownloadButton() { const button=$("#downloadButton"); button.disabled=state.current<0||state.downloadPending; }
function refreshTrackActions() { updateFavoriteButton(); updateDownloadButton(); }
function formatBytes(value) { value=Number(value); if(!Number.isFinite(value)||value<=0)return"0 B"; const units=["B","KB","MB","GB","TB"]; const index=Math.max(0,Math.min(Math.floor(Math.log(value)/Math.log(1024)),units.length-1)); return`${Math.max(1,Math.round(value/1024**index))} ${units[index]}`; }
function showSpeed(rate) { rate=Number(rate); const box=$("#playSpeed"); box.hidden=!state.speedSession||!Number.isFinite(rate)||rate<0; $("#playSpeedValue").textContent=`${formatBytes(rate)}/s`; }
async function pollSpeed() { if(!state.speedSession)return; try { const data=await api(`/api/player/speed/${state.speedSession}`); const now=performance.now(),dt=(now-state.speedTime)/1000; if(dt>=0.9){const total=Number(data&&data.bytes)||0;state.speedRate=Math.max(0,(total-state.speedBytes)/dt);state.speedBytes=total;state.speedTime=now;} showSpeed(state.speedRate); } catch(error) { state.speedSession=null; showSpeed(0); } }
async function downloadCurrent() { const track=state.queue[state.current]; if(!track||state.downloadPending)return; state.downloadPending=true; updateDownloadButton(); try { await api("/api/downloads",{method:"POST",body:JSON.stringify({urls:[`track/${track.id}`],track_quality:localStorage.getItem("tiddl-default-highest")==="true"?"max":"high",atmos:localStorage.getItem("tiddl-default-atmos")==="true"?"allow":"none",resource_metadata:[{title:track.title,subtitle:track.artist,cover:track.cover,type:"track"}]})}); showToast(t("downloadQueued")); } catch(error) { showToast(error.message); } finally { state.downloadPending=false; refreshTrackActions(); } }
function isResource(value) { return /^(?:https?:\/\/(?:listen\.)?tidal\.com\/)?(?:browse\/)?(?:(?:track|album)\/\d+|album\/\d+\/track\/\d+)(?:\?.*)?$/.test(value.trim()); }
async function addResource(resource) { $("#playerSearchResults").hidden=true; $("#searchSpinner").hidden=false; try { const data=await api("/api/player/resource",{method:"POST",body:JSON.stringify({resource})}); const known=new Set(state.queue.map(track=>String(track.id))); const path=resource.replace(/^https?:\/\/(?:listen\.)?tidal\.com\/(?:browse\/)?/,"").split("?")[0]; const trackMatch=path.match(/(?:^|\/)track\/(\d+)$/); const sourceType=trackMatch?"track":"album"; const sourceKey=trackMatch?`track/${trackMatch[1]}`:path; state.queue.push(...data.tracks.filter(track=>!known.has(String(track.id))).map(track=>({...plainTrack(track),_sourceType:sourceType,_sourceKey:sourceKey}))); renderQueue(); $("#playerSearch").value=""; if(state.current<0 && state.queue.length) playIndex(0); } catch(error) { showError(error.message); } finally { $("#searchSpinner").hidden=true; } }
function applyFavoriteFilter() { state.favFilter=$("#playerSearch").value.trim(); renderFavorites(); }
async function search() { if(state.libraryTab==="favorites")return applyFavoriteFilter(); const query=$("#playerSearch").value.trim(); if(query.length<2)return; if(isResource(query)){await addResource(query);return;} const id=++state.searchId; $("#searchSpinner").hidden=false; try { const data=await api(`/api/search?query=${encodeURIComponent(query)}`); if(id===state.searchId)renderResults(data.results); } catch(error){showError(error.message);} finally { if(id===state.searchId)$("#searchSpinner").hidden=true; } }
function showError(message="") { $("#playerError").textContent=message; }
const qualitySpecs={LOW:{label:"96 kbps",tone:"white"},HIGH:{label:"320 kbps",tone:"green"},LOSSLESS:{label:"Lossless · 16/44.1",tone:"gold"},HI_RES_LOSSLESS:{label:"Hi-Res",tone:"magenta"}};
function renderQualityControl() { const actual=state.actualQuality; const selected=actual?.audioMode==="DOLBY_ATMOS"?{label:`Dolby Atmos · ${actual.codec||"immersive"}`,tone:"gold"}:qualitySpecs[state.quality]; const choices=state.availableQualities.filter(value=>qualitySpecs[value]); const locked=state.defaultHighest; const disabled=state.current<0&&!locked; $("#qualityControl").innerHTML=`<div class="spec-control"><button id="qualityButton" class="spec-tag ${disabled?"":`spec-tone-${selected.tone}`}${locked?" locked":""}" type="button" ${disabled?"disabled":""} title="${esc(locked?t("defaultHighestToast"):"")}"><span>${esc(selected.label)}</span><i data-lucide="${locked?"lock":"chevron-down"}"></i></button><div id="qualityMenu" class="spec-menu" hidden>${choices.map(value=>`<button type="button" class="${value===state.quality?"selected":""}" data-quality-choice="${value}"><span>${esc(qualitySpecs[value].label)}</span>${value===state.quality?`<i data-lucide="check"></i>`:""}</button>`).join("")}</div></div>`; icon(); }
function chooseQuality(track) { return track.qualities.includes(state.quality)?state.quality:(track.qualities.includes("LOSSLESS")?"LOSSLESS":"HIGH"); }
function updateQualityOptions(track) { state.availableQualities=[...track.qualities]; state.actualQuality=null; if(state.defaultHighest)state.quality=state.availableQualities.at(-1);else if(!track.qualities.includes(state.quality))state.quality=chooseQuality(track); renderQualityControl(); }
function showActualQuality(data) { if(data.audio_mode==="DOLBY_ATMOS")state.actualQuality={audioMode:data.audio_mode,codec:data.codec};else{state.actualQuality=null;state.quality=data.quality;}renderQualityControl(); }
function supportsPlayerStream(data) { if(data.audio_mode!=="DOLBY_ATMOS")return true; const codec={eac3:"ec-3",ac4:"ac-4"}[String(data.codec).toLowerCase()]||data.codec; return Boolean(audio.canPlayType(`${data.mime_type}; codecs="${codec}"`)); }
function parseLyrics(data) { if(!data)return[]; const lines=[]; for(const line of (data.subtitles||"").split(/\r?\n/)){ const match=line.match(/^\[(\d+):(\d+(?:\.\d+)?)\](.*)$/); if(match)lines.push({time:Number(match[1])*60+Number(match[2]),text:match[3].trim()}); } return lines; }
function renderLyrics(data) { state.lyrics=parseLyrics(data); state.activeLyric=-1; const box=$("#lyrics"); box.scrollTop=0; box.dir=data?.rtl?"rtl":"ltr"; const linesHtml=state.lyrics.length?state.lyrics.map((line,index)=>`<span class="lyrics-line" data-lyric="${index}">${esc(line.text||" ")}</span>`).join(""):""; if(linesHtml)box.innerHTML=linesHtml; else box.textContent=data?.text||t("noLyrics"); renderCoverLyrics(data, linesHtml); }
function renderCoverLyrics(data, linesHtml) { const box=$("#coverLyrics"); box.dir=data?.rtl?"rtl":"ltr"; if(linesHtml)box.innerHTML=linesHtml; else box.textContent=data?.text||t("noLyrics"); if(state.coverLyrics)box.hidden=false; }
function applyArtBackdrop() { const shell=$(".player-shell"), cover=$("#nowCover"); const url=cover&&cover.src; if(url){shell.classList.add("art-backdrop");shell.style.setProperty("--backdrop",`url("${url}")`);}else{shell.classList.remove("art-backdrop");shell.style.removeProperty("--backdrop");} }
function setCoverLyricsMode(on) { const art=$("#nowArt"), box=$("#coverLyrics"), cover=$("#nowCover"); state.coverLyrics=on; art.classList.toggle("lyrics-mode",on); cover.classList.toggle("blurred",on); box.hidden=!on; $(".player-shell").classList.toggle("lyrics-open",on); }
async function playIndex(index) { if(!state.queue.length)return; if(index<0)index=state.queue.length-1; if(index>=state.queue.length)index=0; state.current=index; const track=state.queue[index], request=++state.resolving; renderQueue(); $("#nowTitle").textContent=track.title; $("#nowArtist").textContent=`${track.artist} · ${track.album}`; $("#nowArtist").classList.toggle("artist-link",Boolean(track.artist_id)); $("#nowCover").src=track.cover||""; $("#coverPlaceholder").hidden=Boolean(track.cover); setCoverLyricsMode(false); $("#nowCover").onload=applyArtBackdrop; applyArtBackdrop(); refreshTrackActions(); updateQualityOptions(track); showError(t("loading")); try { const data=await api("/api/player/resolve",{method:"POST",body:JSON.stringify({track_id:track.id,quality:chooseQuality(track),allow_atmos:state.defaultAtmos})}); if(request!==state.resolving)return; state.speedSession=data.session_id; state.speedBytes=0; state.speedTime=performance.now(); state.speedRate=0; state.currentInfo={...data.track,quality:data.quality,audio_mode:data.audio_mode,bit_depth:data.bit_depth,sample_rate:data.sample_rate,codec:data.codec}; state.selectedTrackId=null; state.selectedInfo=null; state.albumInfo=null; showActualQuality(data); if(!supportsPlayerStream(data))throw new Error(t("unsupportedAtmos")); audio.src=data.stream_url; renderLyrics(data.lyrics); safePlay(); showError(); updateMediaSession(track); } catch(error){ if(request===state.resolving)showError(error.message); } }
