  const innerAdd=event.target.closest("[data-inner-add]");
  if(innerAdd){event.stopPropagation();const track=favInnerTrack(innerAdd);if(!track)return;if(state.queue.some(item=>String(item.id)===String(track.id)))return showToast(t("alreadyInQueue"));insertAfterCurrent(track);return;}
